package uigen

import (
	"fmt"
	"strconv"
	"strings"

	"scenery.sh/internal/clientprojection"
)

func renderReactAssistantAdapter(assistants []Resource) string {
	var b strings.Builder
	b.WriteString("// Code generated by Scenery. DO NOT EDIT.\n")
	b.WriteString("import { useCallback, useEffect, useMemo, useState } from \"react\";\n")
	b.WriteString("import * as Runtime from \"../runtime.js\";\n")
	b.WriteString("import { createAssistantClient, type AssistantConversationClient, type AssistantEvent, type AssistantRequestOptions, type AssistantTransportOptions } from \"../assistant.js\";\n\n")
	b.WriteString("export type SceneryAssistantName = ")
	for index, assistant := range assistants {
		if index > 0 {
			b.WriteString(" | ")
		}
		b.WriteString(strconv.Quote(assistant.Name))
	}
	b.WriteString(";\n")
	b.WriteString("export interface SceneryAssistantState { readonly name: SceneryAssistantName; readonly client: AssistantConversationClient; readonly conversationId?: string; readonly runId?: string; readonly events: readonly AssistantEvent[]; readonly pending: boolean; readonly error?: unknown; readonly createConversation: (message: string, options?: AssistantRequestOptions) => Promise<void>; readonly sendTurn: (message: string, options?: AssistantRequestOptions) => Promise<void>; readonly resolveApproval: (approvalId: string, decision: \"approve\" | \"deny\", options?: AssistantRequestOptions) => Promise<void>; readonly cancelRun: (runId?: string, options?: AssistantRequestOptions) => Promise<void> }\n\n")
	b.WriteString("export function useSceneryAssistant(name: SceneryAssistantName, providedClient?: AssistantConversationClient, transport?: AssistantTransportOptions): SceneryAssistantState {\n")
	b.WriteString("  const client = useMemo(() => providedClient ?? createAssistantClient(name, transport ?? { baseUrl: typeof globalThis.location === \"undefined\" ? \"http://localhost\" : globalThis.location.origin, authentication: { credentials: \"include\" } }, {\n")
	for _, assistant := range assistants {
		path := ""
		if surface, ok := assistant.Spec["surface"].(map[string]any); ok {
			path = strings.TrimSuffix(clientprojection.StringValue(surface["path"]), "/")
		}
		fmt.Fprintf(&b, "    %s: %s,\n", strconv.Quote(assistant.Name), strconv.Quote(path))
	}
	b.WriteString("  }), [name, providedClient, transport]);\n")
	b.WriteString("  const [conversationId, setConversationId] = useState<string>();\n  const [runId, setRunId] = useState<string>();\n  const [events, setEvents] = useState<readonly AssistantEvent[]>([]);\n  const [pending, setPending] = useState(false);\n  const [error, setError] = useState<unknown>();\n")
	b.WriteString("  const createConversation = useCallback(async (message: string, options: AssistantRequestOptions = {}) => { setPending(true); setError(undefined); try { const conversation = await client.createConversation({ message }, options); setConversationId(conversation.conversationId); setRunId(conversation.runId); setEvents([]); } catch (cause) { setError(cause); throw cause; } finally { setPending(false); } }, [client]);\n")
	b.WriteString("  const sendTurn = useCallback(async (message: string, options: AssistantRequestOptions = {}) => { if (conversationId === undefined) throw new Error(\"assistant conversation is not open\"); setPending(true); setError(undefined); try { const run = await client.sendTurn(conversationId, { message }, options); setRunId(run.runId); } catch (cause) { setError(cause); throw cause; } finally { setPending(false); } }, [client, conversationId]);\n")
	b.WriteString("  const resolveApproval = useCallback(async (approvalId: string, decision: \"approve\" | \"deny\", options: AssistantRequestOptions = {}) => { if (conversationId === undefined) throw new Error(\"assistant conversation is not open\"); await client.resolveApproval(conversationId, approvalId, decision, options); }, [client, conversationId]);\n")
	b.WriteString("  const cancelRun = useCallback(async (requestedRunId?: string, options: AssistantRequestOptions = {}) => { if (conversationId === undefined || (requestedRunId ?? runId) === undefined) throw new Error(\"assistant run is not open\"); await client.cancelRun(conversationId, requestedRunId ?? runId!, options); }, [client, conversationId, runId]);\n")
	b.WriteString("  useEffect(() => { if (conversationId === undefined) return; const controller = new AbortController(); let active = true; void (async () => { try { for await (const event of client.streamEvents(conversationId, { signal: controller.signal })) { if (!active) return; setEvents((current) => current.some((item) => item.sequence === event.sequence) ? current : [...current, event]); setRunId(event.runId); } } catch (cause) { if (active && !(cause instanceof Error && cause.name === \"AbortError\") && !(cause instanceof Runtime.ClientError && cause.code === \"cancelled\")) setError(cause); } })(); return () => { active = false; controller.abort(); }; }, [client, conversationId]);\n")
	b.WriteString("  return { name, client, conversationId, runId, events, pending, error, createConversation, sendTurn, resolveApproval, cancelRun };\n}\n")
	return b.String()
}
